import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
        c.updateRoundImplementation(payable(address(new Dummy())));
        c.updateAlloSettings(address(new Dummy()));
        c.programOperators(address(this), true);
    }

    function testFuzz_property(bytes calldata encodedParameters, address ownedBy) public {
        vm.assume(ownedBy != address(0));

        // Record the event
        vm.expectEmit(true, true, true, true);
        // We don't know the exact clone yet, so we just check the event is emitted

        address returnedClone = c.create(encodedParameters, ownedBy);
        // The event should have been emitted with the same clone address as returned
        // Since we can't directly check events in fuzz test easily, we check that returnedClone is not address(0) (which would be the bug case)
        assertTrue(returnedClone != address(0));
    }
}

contract Dummy {
    function initialize(bytes calldata, address) external {}
}

