pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes calldata encodedParameters, address ownedBy) public {
        vm.assume(ownedBy != address(0));
        c.updateRoundImplementation(payable(address(1)));
        c.updateAlloSettings(address(2));
        c.programOperators(address(this), true);
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address ret) {
            clone = ret;
        } catch {
            clone = address(0);
        }
        assertTrue(clone != address(0) ? address(uint160(uint256(keccak256(clone.code)))).code.length > 0 : true);
    }
}

