pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes calldata encodedParameters, address ownedBy) public {
        // Make caller a program operator first
        vm.assume(ownedBy != address(0));

        // Set up required state: alloSettings and roundImplementation
        // We need to call updateAlloSettings and updateRoundImplementation via the owner
        // Since the owner is the deployer (this contract), we can do that
        c.updateAlloSettings(address(0x1234));
        c.updateRoundImplementation(payable(address(0x5678)));

        // Set the msg.sender as program operator to pass the modifier
        vm.prank(address(this));
        // We need to set programOperators for the caller - but the modifier checks msg.sender
        // Since we are calling from this contract, we need to set it for this contract address
        // Unfortunately programOperators is a mapping we can set via the public function
        // But there's no external setter - we can use vm.store or we can call via the contract
        // The contract has a public mapping programOperators - we need to set it
        // We can use vm.store to set the mapping value
        vm.store(address(c), keccak256(abi.encode(address(this), uint256(0))), bytes32(uint256(1)));

        // Now call create
        address clone = c.create(encodedParameters, ownedBy);

        // Assert that clone has code (is a contract)
        assertTrue(clone.code.length > 0);
    }
}

