pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes memory encodedParameters, address ownedBy) public {
        vm.assume(caller != address(0));
        vm.assume(ownedBy != address(0));

        // Deploy C and set up the caller as a program operator
        vm.prank(caller);
        c.initialize();

        // Set caller as program operator
        vm.store(address(c), keccak256(abi.encode(caller, uint256(4))), bytes32(uint256(1))); // hack: set programOperators[caller] = true
        // Since storage slot calculation is complex, we use a direct prank to call addProgramOperator if available - but not present, so we'll use vm.store
        // Actually, we need to call the function to add operator, but it's not public. Use vm.store to set the mapping directly.
        // Simpler: just make the caller the owner and use the modifier bypass via vm.store for programOperators
        // Let's directly set programOperators mapping via vm.store
        // slot for mapping: keccak256(abi.encode(key, slot)) where slot of programOperators is 4 (after OwnableUpgradeable's __gap_2 of 49 slots and _owner slot)
        bytes32 slot = keccak256(abi.encode(caller, uint256(4)));
        vm.store(address(c), slot, bytes32(uint256(1)));

        // Set both addresses to zero to trigger failure case
        vm.prank(caller);
        c.updateAlloSettings(address(0));
        vm.prank(caller);
        c.updateRoundImplementation(payable(address(0)));

        // try to call create - it should revert
        vm.prank(caller);
        bool reverted = false;
        try c.create(encodedParameters, ownedBy) {
            // success
        } catch {
            reverted = true;
        }

        assertTrue(reverted, "create should revert when both addresses are zero");
    }
}

