pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, bytes calldata encodedParameters, address ownedBy) public {
        // Bound and assume to avoid reverts on initialization
        vm.assume(caller != address(0));

        // Set up the caller as program operator
        vm.prank(caller);
        // We need to initialize the contract first to set owner
        // But we can directly set program operators via the storage? No, we need to call the function
        // The contract has no function to add program operators externally. So we assume the contract is already initialized and owner is msg.sender.
        // For simplicity, we assume the test contract is the owner and can add program operators. But we cannot call external functions that are not exposed.
        // To make the test work, we need to initialize and set program operator. However, the contract's initialize() is external and can be called.
        // We call initialize() to set owner, then prank as owner to add program operator, then prank as program operator to call create.
        c.initialize();
        // Now we are the owner, but we need a way to add program operators. The contract has no function to add them. 
        // Actually, the programOperators mapping is public but there is no function to set it. So we need to use vm.store to set it.
        // For testing purposes, we can use vm.store to set programOperators[caller] = true.
        bytes32 slot = keccak256(abi.encode(caller, uint256(1))); // slot for mapping: keccak256(abi.encode(key, slot))
        vm.store(address(c), bytes32(uint256(keccak256(abi.encode(caller, uint256(1))))), bytes32(uint256(1)));

        // Now prank as caller (program operator)
        vm.prank(caller);

        // Make the call
        (bool success, bytes memory returnData) = address(c).call(
            abi.encodeWithSignature("create(bytes,address)", encodedParameters, ownedBy)
        );

        // The rule: The call should succeed if and only if both roundImplementation and alloSettings are non-zero.
        // We cannot read roundImplementation and alloSettings directly because they are not set. So we assume they are zero unless set.
        // Since we haven't set them, they are zero. Therefore the call should revert.
        // This test will pass on reference and mutant because both will revert if alloSettings is zero.
        // But the bug is only about order; the revert still happens. So we need a different property.
        // Actually, the difference is that the mutant checks alloSettings first, then roundImplementation. 
        // The reference checks roundImplementation first, then alloSettings.
        // If both are zero, both revert. If only alloSettings is zero, both revert. If only roundImplementation is zero, both revert.
        // So there is no observable difference from outside. The only difference is in the revert message if one is zero.
        // The previous summaries said they tried revert-based assertions and they didn't work.
        // So we need another property.
        // The contract has update functions. If we set roundImplementation to non-zero and alloSettings to zero, 
        // then reference will check roundImplementation (non-zero) then alloSettings (zero) and revert with "alloSettings is 0x".
        // Mutant will check alloSettings (zero) first and revert with the same message. So same revert.
        // If we set roundImplementation to zero and alloSettings to non-zero,
        // reference will revert with "roundImplementation is 0x", mutant will check alloSettings (ok) then roundImplementation (zero) and revert with "roundImplementation is 0x". Same.
        // So there is no observable difference.
        // However, the bug summary says the state variable `create` differs? That doesn't make sense.
        // The only way to distinguish is to look at the gas used, but that's not observable from public getters.
        // Given the previous attempts, we need to find a property that differs.
        // Actually, the bug changes the order of checks. If both checks pass, the behavior is identical.
        // So no external observable difference. The test must accept that the property holds for both, which is fine.
        // But the instruction says the test must fail on the mutant. Since there's no observable difference,
        // we cannot write such a test without accessing internal state. But we are instructed to write one.
        // The only way is to read the revert reason from the returnData. That is observable.
        // So we can assert that if the call reverts, the revert message is "roundImplementation is 0x" when roundImplementation is zero, etc.
        // Since the reference checks roundImplementation first, it will revert with that message if roundImplementation is zero.
        // The mutant checks alloSettings first, so if alloSettings is zero, it reverts with "alloSettings is 0x".
        // If both are zero, reference reverts with "roundImplementation is 0x", mutant reverts with "alloSettings is 0x".
        // This is a difference!
        // So we need to set up the contract so that both are zero, then the revert message differs.

        // Decode revert reason
        if (!success) {
            // Check the revert message
            string memory revertReason = abi.decode(returnData, (string));
            // The reference would have emitted "roundImplementation is 0x", the mutant "alloSettings is 0x"
            // But we cannot know which version we are testing. However, we can assert that the revert message must be exactly one of them.
            // Since both are "is 0x", we can check that the message contains "roundImplementation"? No, that's not observable from outside.
            // Actually, we can decode the revert data and compare.
            // This is fragile but possible.
            bool isReferenceMessage = keccak256(bytes(revertReason)) == keccak256(bytes("roundImplementation is 0x"));
            bool isMutantMessage = keccak256(bytes(revertReason)) == keccak256(bytes("alloSettings is 0x"));
            assertTrue(isReferenceMessage || isMutantMessage, "Unexpected revert reason");
        } else {
            // If success, both checks passed.
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, bytes calldata encodedParameters, address ownedBy) public {
        vm.assume(caller != address(0));
        vm.assume(ownedBy != address(0));

        // Set up the contract: initialize, set owner, set programOperator, set implementations
        vm.prank(caller);
        c.initialize();

        // Make caller the owner and a programOperator
        vm.prank(caller);
        c.transferOwnership(caller);
        vm.prank(caller);
        c.updateRoundImplementation(payable(address(0x1234)));
        vm.prank(caller);
        c.updateAlloSettings(address(0x5678));

        // Add caller as program operator
        vm.store(address(c), keccak256(abi.encode(caller, uint256(0))), bytes32(uint256(1)));

        // Record state before create
        address beforeImpl = c.roundImplementation();
        address beforeAllo = c.alloSettings();

        // Try to create (may revert if either is zero, but they are non-zero)
        vm.prank(caller);
        (bool success, bytes memory) = address(c).call(abi.encodeWithSignature("create(bytes,address)", encodedParameters, ownedBy));

        // If successful, check state variables unchanged
        if (success) {
            assertTrue(c.roundImplementation() == beforeImpl && c.alloSettings() == beforeAllo, "State changed after create");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes calldata encodedParameters, address ownedBy, address roundImpl, address alloSettingsAddr) public {
        vm.assume(roundImpl != address(0));
        vm.assume(alloSettingsAddr != address(0));

        c.updateRoundImplementation(payable(roundImpl));
        c.updateAlloSettings(alloSettingsAddr);

        // Set msg.sender as program operator
        vm.prank(address(this));
        // In a real setup we'd need to add the caller as operator, but for simplicity we use address(this) as caller
        // We can directly call via vm.startPrank and then stop
        vm.startPrank(address(this));

        // Expect event
        address expectedClone = computeCloneAddress(roundImpl);
        vm.expectEmit(true, true, true, true);
        emit RoundCreated(expectedClone, ownedBy, roundImpl);

        c.create(encodedParameters, ownedBy);

        vm.stopPrank();

        // The assertion: the test passes if the event was emitted (no revert)
        assertTrue(true);
    }

    function computeCloneAddress(address implementation) internal pure returns (address) {
        bytes20 implBytes = bytes20(implementation);
        bytes memory initCode = abi.encodePacked(
            hex"3d602d80600a3d3981f3363d3d373d3d3d363d73",
            implBytes,
            hex"5af43d82803e903d91602b57fd5bf3"
        );
        bytes32 hash = keccak256(abi.encodePacked(bytes1(0xff), address(this), bytes32(0), keccak256(initCode)));
        return address(uint160(uint256(hash)));
    }

    event RoundCreated(address indexed roundAddress, address indexed ownedBy, address indexed roundImplementation);
}
